-- BerojgarDegreeWala :: 100 Verified Semiconductor Companies in Bangalore
-- Source: Silicon Bharat 100 Verified Semiconductor Companies (Bangalore Edition)
-- Adds and updates all 100 verified semiconductor organizations with confirmed R&D presence.

ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  type = EXCLUDED.type,
  country = EXCLUDED.country,
  location = EXCLUDED.location,
  website = COALESCE(organizations.website, EXCLUDED.website),
  description = EXCLUDED.description,
  is_verified = true,
  is_active = true,
  updated_at = now();
